import re

def eval_expression(expr):
    """Evaluate expressions containing +, -, *, /, parentheses, and unary signs."""
    number_pattern = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)")
    pos = 0

    def skip_whitespace():
        nonlocal pos
        while pos < len(expr) and expr[pos].isspace():
            pos += 1

    def parse_expression():
        nonlocal pos
        value = parse_term()

        while True:
            skip_whitespace()
            if pos >= len(expr) or expr[pos] not in "+-":
                return value

            operator = expr[pos]
            pos += 1
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

    def parse_term():
        nonlocal pos
        value = parse_factor()

        while True:
            skip_whitespace()
            if pos >= len(expr) or expr[pos] not in "*/":
                return value

            operator = expr[pos]
            pos += 1
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

    def parse_factor():
        nonlocal pos
        skip_whitespace()

        if pos >= len(expr):
            raise ValueError("Expected a number or parentheses")

        # Support unary + and -
        if expr[pos] in "+-":
            operator = expr[pos]
            pos += 1
            value = parse_factor()
            return -value if operator == "-" else value

        # Parenthesized expression
        if expr[pos] == "(":
            pos += 1
            value = parse_expression()
            skip_whitespace()

            if pos >= len(expr) or expr[pos] != ")":
                raise ValueError("Missing closing parenthesis")

            pos += 1
            return value

        # Number
        match = number_pattern.match(expr, pos)
        if not match:
            raise ValueError(f"Unexpected character at position {pos}")

        token = match.group()
        pos = match.end()
        return float(token) if "." in token else int(token)

    result = parse_expression()
    skip_whitespace()

    if pos != len(expr):
        raise ValueError(f"Unexpected character at position {pos}")

    return result
